#!/system/bin/sh
# =============================================================================
# vendor_fix_install.sh — "Vendor修复模块" 一键安装器
# (sensor_vendor_fix systemless 模块, Magisk / KernelSU / APatch 通用)
#
# 背景:
#   本脚本内嵌 sensor_vendor_fix 模块的全部文件(module.prop / post-fs-data.sh /
#   system/lib(64)/libsensorservice.so), 无需刷 zip、无需手动拷贝,
#   一条命令把模块装进 /data/adb/modules, 重启后由 Root 管理器 systemless 挂载,
#   不动 system 分区。
#
#   模块作用: 将 SensorService 虚拟传感器 vendor 的 "AOSP" 改写为 "MTK!",
#   规避风控 SDK 的 "Miscellaneous Check(5)"(vendor 含 AOSP 的传感器 >3 判模拟器)。
#
# 用法:
#   sh vendor_fix_install.sh [apply|restore|status]
#     apply    安装模块(默认); 已安装则覆盖更新
#     restore  移除模块(重启后恢复原状)
#     status   查看安装状态与传感器 vendor 统计
#
# 环境变量(可选,一般不用管):
#   VFI_MODROOT   模块根目录,默认 /data/adb/modules
#   VFI_ZIP       外部模块 zip 路径,设置后优先解包该 zip(需系统有 unzip)
#   VFI_REBOOT    =1 时动作完成后自动重启(默认不重启,只提示)
#
# 注意:
#   - 必须已 root (Magisk/KernelSU/APatch), 先执行 su 再运行本脚本
#   - 安装/还原后都需重启生效
#   - OTA 或模块更新后直接重新 apply 即可, 无需先 restore
# =============================================================================

# ---------- 可调参数 ----------
MOD_ID=${VFI_MOD_ID:-"sensor_vendor_fix"}
MODROOT=${VFI_MODROOT:-"/data/adb/modules"}
MOD_DIR="$MODROOT/$MOD_ID"
WORK=${VFI_WORK:-"/data/local/tmp/vendor_fix_install"}
PKG="$WORK/pkg"
CMD=${1:-apply}

# ---------- 工具函数 ----------
msg()  { printf "[*] %s\n" "$1"; }
ok()   { printf "[✓] %s\n" "$1"; }
warn() { printf "[!] %s\n" "$1"; }
die()  { printf "[✗] %s\n" "$1"; exit 1; }

need_root() {
    [ "$(id -u)" = "0" ] || die "需要 root 权限: 请先执行 su 再运行本脚本 (当前 uid=$(id -u))"
}

detect_root() {
    if   [ -d /data/adb/ksu ];    then echo "KernelSU"
    elif [ -d /data/adb/ap ];     then echo "APatch"
    elif [ -d /data/adb/magisk ]; then echo "Magisk"
    else echo "未识别"
    fi
}

# 取文件的 SELinux 标签; 取不到则回退默认值
get_label() {
    L=$(ls -Z "$1" 2>/dev/null | awk '{print $1}')
    case "$L" in
        u:object_r:*) echo "$L" ;;
        *) echo "u:object_r:system_lib_file:s0" ;;
    esac
}

# 校验 ELF magic (\177ELF)
is_elf() {
    [ "$(head -c 4 "$1" 2>/dev/null | tr -d '\177')" = "ELF" ]
}

# ---------- 解包模块 ----------
unpack() {
    rm -rf "$WORK"; mkdir -p "$WORK" || die "无法创建工作目录 $WORK"

    # 外部 zip 优先(需 unzip), 否则用内嵌数据
    if [ -n "$VFI_ZIP" ]; then
        [ -f "$VFI_ZIP" ] || die "VFI_ZIP 不存在: $VFI_ZIP"
        if command -v unzip >/dev/null 2>&1; then
            msg "解包外部 zip: $VFI_ZIP"
            mkdir -p "$PKG" || die "无法创建 $PKG"
            unzip -o -q "$VFI_ZIP" -d "$PKG" || die "解压失败: $VFI_ZIP"
            return 0
        fi
        warn "系统无 unzip, 回退到内嵌模块数据"
    fi

    msg "解包内嵌模块数据"
    mkdir -p "$PKG/system/lib" "$PKG/system/lib64" || die "无法创建 $PKG"
    command -v base64 >/dev/null 2>&1 || die "缺少 base64 命令, 无法解包内嵌数据"

    base64 -d > "$PKG/module.prop" <<'B64_MODULE_PROP' || die "解码失败: module.prop"
aWQ9c2Vuc29yX3ZlbmRvcl9maXgKbmFtZT1TZW5zb3IgVmVuZG9yIFNhbml0aXplCnZlcnNpb249
Mi4wCnZlcnNpb25Db2RlPTIKYXV0aG9yPUhvc2hpbm9PVk8sU2h1b2gxMTgKZGVzY3JpcHRpb249
