B64_SO32
    [ -s "$PKG/system/lib/libsensorservice.so" ] || die "解码失败: lib"
}

# ---------- 动作 ----------
do_apply() {
    need_root
    msg "Vendor修复模块 安装器 | $(date "+%Y-%m-%d %H:%M:%S")"
    msg "Root 环境: $(detect_root)"

    unpack

    [ -f "$PKG/module.prop" ] || die "模块包缺少 module.prop"
    PKG_ID=$(grep -m1 '^id=' "$PKG/module.prop" 2>/dev/null | cut -d= -f2 | tr -d '\r')
    [ -n "$PKG_ID" ] || die "无法从 module.prop 读取 id"
    if [ "$PKG_ID" != "$MOD_ID" ]; then
        warn "模块 id ($PKG_ID) 与默认 ($MOD_ID) 不一致, 按包内 id 安装"
        MOD_ID="$PKG_ID"; MOD_DIR="$MODROOT/$MOD_ID"
    fi

    FOUND=0
    for SO in "$PKG/system/lib64/libsensorservice.so" "$PKG/system/lib/libsensorservice.so"; do
        [ -f "$SO" ] || continue
        FOUND=$((FOUND + 1))
        is_elf "$SO" || die "文件损坏或不是有效的 ELF 库: $SO"
    done
    [ "$FOUND" -gt 0 ] || die "模块包内未找到 libsensorservice.so"

    # 冲突检测: 其他模块也替换 libsensorservice.so
    CONFLICTS=""
    for DIR in "$MODROOT"/*/; do
        [ -d "$DIR" ] || continue
        D=$(basename "${DIR%/}")
        [ "$D" = "$MOD_ID" ] && continue
        [ -f "${DIR}disable" ] && continue
        [ -f "${DIR}remove" ] && continue
        if [ -f "${DIR}system/lib/libsensorservice.so" ] || [ -f "${DIR}system/lib64/libsensorservice.so" ]; then
            CONFLICTS="$CONFLICTS $D"
        fi
    done
    [ -z "$CONFLICTS" ] || warn "以下模块也替换了 libsensorservice.so, 同时启用会互相覆盖: $CONFLICTS"

    # 安装
    msg "安装到: $MOD_DIR"
    rm -rf "$MOD_DIR" || die "删除旧模块失败"
    mkdir -p "$MOD_DIR/system/lib" "$MOD_DIR/system/lib64" || die "无法创建模块目录 $MOD_DIR"

    cp -f "$PKG/module.prop" "$MOD_DIR/module.prop" || die "拷贝 module.prop 失败"
    cp -f "$PKG/post-fs-data.sh" "$MOD_DIR/post-fs-data.sh" || die "拷贝 post-fs-data.sh 失败"

    for SUB in lib lib64; do
        SRC="$PKG/system/$SUB/libsensorservice.so"
        DST="$MOD_DIR/system/$SUB/libsensorservice.so"
        [ -f "$SRC" ] || continue
        cp -f "$SRC" "$DST" || die "拷贝失败: $SUB"
        LBL=$(get_label "/system/$SUB/libsensorservice.so")
        chcon "$LBL" "$DST" 2>/dev/null || warn "无法设置 SELinux 标签 $LBL (开机时 post-fs-data.sh 会兜底)"
        ok "已写入 system/$SUB/libsensorservice.so (标签 $LBL)"
    done

    # post-fs-data.sh 内的路径跟随自定义 MODROOT
    if [ "$MOD_DIR" != "/data/adb/modules/sensor_vendor_fix" ]; then
        sed "s|/data/adb/modules/sensor_vendor_fix|$MOD_DIR|g" "$PKG/post-fs-data.sh" > "$MOD_DIR/post-fs-data.sh" 2>/dev/null || warn "post-fs-data.sh 路径修正失败"
    fi

    chown -R 0:0 "$MOD_DIR" 2>/dev/null
    chmod 644 "$MOD_DIR/module.prop" 2>/dev/null
    chmod 644 "$MOD_DIR"/system/lib*/libsensorservice.so 2>/dev/null
    chmod 755 "$MOD_DIR/post-fs-data.sh" 2>/dev/null

    echo ""
    ok "模块已安装: $MOD_DIR"
    ok "重启后生效。验证命令:"
    echo '    su -c "dumpsys sensorservice | grep -ci aosp"     # 期望 0'
    echo '    su -c "dumpsys sensorservice | grep -ci MTK!"     # 应 > 0'
    echo ""
    warn "OTA/大版本升级后, 直接重新 apply 即可覆盖更新"

    if [ "$VFI_REBOOT" = "1" ]; then
        msg "VFI_REBOOT=1, 3 秒后自动重启..."
        sleep 3
        reboot 2>/dev/null || svc power reboot 2>/dev/null || warn "自动重启失败, 请手动重启"
    fi
}

do_restore() {
    need_root
    if [ -d "$MOD_DIR" ]; then
        rm -rf "$MOD_DIR" || die "删除失败: $MOD_DIR"
        ok "模块已移除: $MOD_DIR"
        ok "重启后恢复原状"
    else
        ok "模块不存在, 无需还原: $MOD_DIR"
    fi
    rm -rf "$WORK"
    if [ "$VFI_REBOOT" = "1" ]; then
        msg "VFI_REBOOT=1, 3 秒后自动重启..."
        sleep 3
        reboot 2>/dev/null || svc power reboot 2>/dev/null || warn "自动重启失败, 请手动重启"
    fi
}

do_status() {
    echo "=== 模块 ($MOD_ID) ==="
    if [ -d "$MOD_DIR" ]; then
        echo "已安装: $MOD_DIR"
        if [ -f "$MOD_DIR/disable" ]; then
            echo "状态: 已禁用 (disable 标记存在)"
        else
            echo "状态: 启用"
        fi
        [ -f "$MOD_DIR/remove" ] && echo "状态: 待移除 (remove 标记存在, 重启后删除)"
        ls -l "$MOD_DIR/module.prop" "$MOD_DIR/post-fs-data.sh" "$MOD_DIR"/system/lib*/libsensorservice.so 2>/dev/null
    else
        echo "未安装: $MOD_DIR"
    fi
    echo "=== 运行中传感器 vendor ==="
    if ! command -v dumpsys >/dev/null 2>&1; then
        echo "dumpsys 不可用(此项仅设备上有意义)"
    else
        A=$(dumpsys sensorservice 2>/dev/null | grep -ci aosp)
        T=$(dumpsys sensorservice 2>/dev/null | grep -ci "MTK!")
        echo "含 AOSP 计数: $A | 含 MTK! 计数: $T"
        case "$A" in
            0) [ "$T" -ge 1 ] && echo "结论: ✓ 已改写" || echo "结论: ✓ 无 AOSP 特征" ;;
            *) [ "$A" -gt 3 ] && echo "结论: ✗ 超阈值(>3),检测(5)会命中" || echo "结论: 未超阈值(≤3)" ;;
        esac
    fi
}

# ---------- 入口 ----------
case "$CMD" in
    apply)   do_apply ;;
    restore) do_restore ;;
    status)  do_status ;;
    *) die "用法: sh $0 [apply|restore|status]" ;;
esac
